#!/usr/bin/env python3
"""Checkers (Draughts): 8x8 board, two players, standard capture/kinging rules.

Moves are entered as from-to squares, e.g. 'b6-a5' or '6,2-5,1'.
Rows are numbered 1-8 from bottom to top, columns a-h from left to right.
"""

ROWS = COLS = 8


def playable(r, c):
    return (r + c) % 2 == 1


def initial_board():
    board = [['.'] * COLS for _ in range(ROWS)]
    for r in range(ROWS):
        for c in range(COLS):
            if playable(r, c):
                if r < 3:
                    board[r][c] = 'b'
                elif r > 4:
                    board[r][c] = 'r'
    return board


def sq_name(r, c):
    return f"{chr(ord('a') + c)}{8 - r}"


def parse_square(text):
    s = text.strip().lower()
    if len(s) == 2 and s[0].isalpha() and s[1].isdigit():
        r, c = 8 - int(s[1]), ord(s[0]) - ord('a')
    else:
        a, b = s.split(',')
        r, c = int(a) - 1, int(b) - 1
    if not (0 <= r < ROWS and 0 <= c < COLS):
        raise ValueError('off board')
    return r, c


def dirs(piece):
    if piece in 'RB':
        return ((-1, -1), (-1, 1), (1, -1), (1, 1))
    fwd = -1 if piece == 'r' else 1
    return ((fwd, -1), (fwd, 1))


def jumps_from(board, r, c):
    piece, me = board[r][c], board[r][c].lower()
    out = []
    for dr, dc in dirs(piece):
        mr, mc, tr, tc = r + dr, c + dc, r + 2 * dr, c + 2 * dc
        if 0 <= tr < ROWS and 0 <= tc < COLS:
            mid = board[mr][mc]
            if mid != '.' and mid.lower() != me and board[tr][tc] == '.':
                out.append((tr, tc))
    return out


def slides_from(board, r, c):
    out = []
    for dr, dc in dirs(board[r][c]):
        tr, tc = r + dr, c + dc
        if 0 <= tr < ROWS and 0 <= tc < COLS and board[tr][tc] == '.':
            out.append((tr, tc))
    return out


def moves_for(board, player):
    """Return (moves, capture_required). moves maps (r,c)->[(r,c),...]."""
    caps, slides = {}, {}
    for r in range(ROWS):
        for c in range(COLS):
            if board[r][c].lower() == player:
                if jumps_from(board, r, c):
                    caps[(r, c)] = jumps_from(board, r, c)
                elif slides_from(board, r, c):
                    slides[(r, c)] = slides_from(board, r, c)
    if caps:
        return caps, True
    return slides, False
